import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { z } from "zod";
import { AgentDocZ } from "../src/schema.js";
import { loadAtlas } from "../src/atlas.js";

// The agent.json contract (#169). `fixtures/emitted` is GENERATED by the Julia emitter
// (test/test_contract.jl regenerates it and fails on drift), so these tests check the consumer
// against what Pinax actually writes rather than a hand-written sample.
const here = dirname(fileURLToPath(import.meta.url));
const emitted = resolve(here, "../../test/fixtures/emitted");
const raw = JSON.parse(readFileSync(resolve(emitted, "agent.json"), "utf8"));

// Every object key in `value` that `schema` does not name, as dotted paths. The schema is
// `.passthrough()` so an OLDER consumer survives a newer emitter — which is exactly why a key the
// emitter writes and the schema forgot would otherwise go unnoticed.
function unnamedKeys(schema: z.ZodTypeAny, value: unknown, path: string): string[] {
  if (schema instanceof z.ZodLazy) return unnamedKeys(schema.schema, value, path);
  if (schema instanceof z.ZodOptional || schema instanceof z.ZodNullable) {
    return value == null ? [] : unnamedKeys(schema.unwrap(), value, path);
  }
  if (schema instanceof z.ZodArray && Array.isArray(value)) {
    return value.flatMap((v, i) => unnamedKeys(schema.element, v, `${path}[${i}]`));
  }
  if (schema instanceof z.ZodObject && value !== null && typeof value === "object") {
    const shape = schema.shape as Record<string, z.ZodTypeAny>;
    return Object.entries(value as Record<string, unknown>).flatMap(([k, v]) =>
      k in shape ? unnamedKeys(shape[k], v, `${path}.${k}`) : [`${path}.${k}`],
    );
  }
  return []; // a scalar, a union of scalars, a record of params, or z.unknown()
}

test("the emitted fixture parses against the schema", () => {
  const r = AgentDocZ.safeParse(raw);
  assert.ok(r.success, r.success ? "" : JSON.stringify(r.error.issues, null, 2));
});

test("the schema names every key the emitter writes", () => {
  assert.deepEqual(unnamedKeys(AgentDocZ, raw, "$"), []);
});

test("every content ref in the emitted fixture resolves to a unit", () => {
  const atlas = loadAtlas(emitted);
  const missing: string[] = [];
  const walk = (c: { content?: { kind: string; id: string }[]; sections?: unknown[] }) => {
    for (const ref of c.content ?? []) if (!atlas.unit(ref.id)) missing.push(`${ref.kind}:${ref.id}`);
    for (const s of c.sections ?? []) walk(s as typeof c);
  };
  atlas.doc.pages.forEach(walk);
  assert.deepEqual(missing, []);
});
